  /** The shape and element types of each measured form: K, then A, B, C and D. */
  private val forms: Map[String, (k: Int, a: Element, b: Element, c: Element, d: Element)] = Map(
    "F16_F32_K16"      -> (16, Element.F16, Element.F16, Element.F32, Element.F32),
    "BF16_F32_K16"     -> (16, Element.BF16, Element.BF16, Element.F32, Element.F32),
    "TF32_K8"          -> (8, Element.TF32, Element.TF32, Element.F32, Element.F32),
    "F16_F16_K16"      -> (16, Element.F16, Element.F16, Element.F16, Element.F16),
    "E4M3_F32_K32"     -> (32, Element.E4M3, Element.E4M3, Element.F32, Element.F32),
    "E4M3E5M2_F32_K32" -> (32, Element.E4M3, Element.E5M2, Element.F32, Element.F32),
    "E5M2_F16_K32"     -> (32, Element.E5M2, Element.E5M2, Element.F16, Element.F16),
    "E4M3_F32_K16"     -> (16, Element.E4M3, Element.E4M3, Element.F32, Element.F32),
    "M884_F32_F32"     -> (4, Element.F16, Element.F16, Element.F32, Element.F32),
    "M884_F16_F16"     -> (4, Element.F16, Element.F16, Element.F16, Element.F16),
    "F64_M884"         -> (4, Element.F64, Element.F64, Element.F64, Element.F64),
    "S8_K32"           -> (32, Element.S8, Element.S8, Element.S32, Element.S32),
    "S8_K32_SAT"       -> (32, Element.S8, Element.S8, Element.S32, Element.S32)
  )

  private def evaluate(
      form: (k: Int, a: Element, b: Element, c: Element, d: Element),
      saturate: Boolean,
      a: Vec[Long],
      b: Vec[Long],
      c: Long
  ): Long = {
    val shape = if (form.k == 4) Shape(8, 8, 4) else Shape(16, 8, form.k.unsafe[Int > 0])
    def fragment(role: Role, element: Element) = Fragment(shape, role, element, wmma = false, role == Role.B)
    val format = if (form.a == Element.F64 || form.a.integer) form.d else Matrix.accumulator(form.c, form.d)
    val operation: Operation.Multiply = Operation.Multiply(
      fragment(Role.A, form.a),
      fragment(Role.B, form.b),
      fragment(Role.C, form.c),
      fragment(Role.C, form.d),
      Vec.empty,
      Vec.empty,
      Vec.empty,
      Vec.empty,
      Matrix.accumulation(89, shape, form.a, format, ConversionRounding.RN),
      saturate
    )
    def code(element: Element, bits: Long): Long =
      if (element == Element.S8) bits.toByte.toLong else element.code(bits)
    val inputs = (if (form.c == Element.S32) c.toInt.toLong else c) +:
      a.zip(b).flatMap((x, y) => Vec(code(form.a, x), code(form.b, y)))
    NvidiaMemoryStaged.multiply(Execute, operation)(Probe(inputs*))(Vector.empty).head
  }

  measured.groupBy(_.takeWhile(_ != ' ')).toVector.sortBy(_._1).foreach { (name, vectors) =>
    test(s"$name matches the measured results bit for bit") {
      val form = forms(name)
      vectors.foreach { line =>
        val Array(a, b, c, d)              = line.dropWhile(_ != ' ').trim.split('|')
        def words(text: String): Vec[Long] = Vec.from(text.split(',').map(java.lang.Long.parseUnsignedLong(_, 16)))
        val obtained                       =
          evaluate(form, name.endsWith("_SAT"), words(a), words(b), java.lang.Long.parseUnsignedLong(c, 16))
        val width = form.d.bits
        val mask  = if (width == 64) -1L else (1L << width) - 1L
        assertEquals((obtained & mask).toHexString, d, line)
      }
    }
  }
}
